// Format message: turn one notify input {kind, title, body, url, attempts?, region?, shape?} into a Discord payload.
// Limits: content 2000 characters, embed description 4096, at most 10 embeds. Longer text is cut with '…'.
const LIMIT_CONTENT = 2000;
const LIMIT_DESCRIPTION = 4096;
const LIMIT_FIELD_VALUE = 1024;
const LIMIT_EMBEDS = 10;
const COLORS = { offer: 0x3498db, claim: 0x2ecc71, failure: 0xe74c3c, summary: 0x95a5a6, alert: 0xf39c12 };

// Cut text to max characters (code points). Adds '…' only when it had to cut.
function clip(text, max) {
  const chars = Array.from(String(text ?? ''));
  return chars.length <= max ? chars.join('') : chars.slice(0, max - 1).join('') + '…';
}

const item = $input.first().json;
if (!Object.hasOwn(COLORS, item.kind)) {
  throw new Error(`notify-discord: unknown kind '${item.kind}'`);
}
if (!item.title) {
  throw new Error('notify-discord: title is required');
}

// Claim results carry the attempt count, region and shape as optional fields.
const fields = [];
if (item.kind === 'claim') {
  if (item.attempts !== undefined) fields.push({ name: 'Attempts', value: String(item.attempts), inline: true });
  if (item.region) fields.push({ name: 'Region', value: clip(item.region, LIMIT_FIELD_VALUE), inline: true });
  if (item.shape) fields.push({ name: 'Shape', value: clip(item.shape, LIMIT_FIELD_VALUE), inline: true });
}

// The URL goes in the content so Discord shows it as a clickable link.
const content = clip([item.title, item.url].filter(Boolean).join('\n'), LIMIT_CONTENT);

const embed = { color: COLORS[item.kind] };
if (item.body) embed.description = clip(item.body, LIMIT_DESCRIPTION);
if (fields.length) embed.fields = fields;
const embeds = (embed.description || fields.length ? [embed] : []).slice(0, LIMIT_EMBEDS);

return [{ json: { username: 'VM Hunter', content, embeds } }];

// Resolve thread: pick the forum thread for this message's kind and pass the message on with that id.
// The kind's setting wins when it is set and not blank; otherwise HUNTER_DISCORD_THREAD_ID is used.
const THREAD_SETTINGS = { offer: 'HUNTER_DISCORD_THREAD_OFFERS', claim: 'HUNTER_DISCORD_THREAD_CLAIMS', failure: 'HUNTER_DISCORD_THREAD_FAILURES', summary: 'HUNTER_DISCORD_THREAD_SUMMARY', alert: 'HUNTER_DISCORD_THREAD_SUMMARY' };
const FALLBACK_SETTING = 'HUNTER_DISCORD_THREAD_ID';

// Return the thread id for kind from env, or throw naming the kind and every setting it checked.
function resolveThread(kind, env) {
  const checked = [Object.hasOwn(THREAD_SETTINGS, kind) ? THREAD_SETTINGS[kind] : null, FALLBACK_SETTING].filter(Boolean);
  for (const name of checked) {
    const value = String(env[name] ?? '').trim();
    if (value) return value;
  }
  throw new Error(`notify-discord: no Discord thread for kind '${kind}' (checked ${checked.join(', ')})`);
}

const kind = $('Notify input').first().json.kind;
const threadId = resolveThread(kind, $env);
return [{ json: { threadId, message: $input.first().json } }];

// Check delivery: pass the response on when Discord answered 2xx (204 is success); otherwise fail the run so the error workflow reports it.
const response = $input.first().json;
if (response.statusCode < 200 || response.statusCode > 299) {
  throw new Error(`notify-discord: Discord returned HTTP ${response.statusCode}`);
}

return [{ json: response }];

// Count delivery: after a successful run, count it in the notifier's static data. sent +1 on a 204; rateLimited +1 when the first post was a 429, even if the retry got through.
// Runs only after Check delivery, so a failed run is never counted here (see the monitoring skill).
function countDelivery(metrics, firstStatus, finalStatus) {
  const counters = { sent: 0, rateLimited: 0, ...(metrics?.counters ?? {}) };
  if (finalStatus === 204) counters.sent += 1;
  if (firstStatus === 429) counters.rateLimited += 1;
  return { ...(metrics ?? {}), counters };
}

const data = $getWorkflowStaticData('global');
data.metrics = countDelivery(data.metrics, $('Post to Discord').first().json.statusCode, $input.first().json.statusCode);
return [{ json: $input.first().json }];
